FUNCTION_BLOCK FB_ConveyorTest
VAR_INPUT
    RunCmd : BOOL;
    PE_Sensor : BOOL;
END_VAR
VAR_OUTPUT
    MotorOut : BOOL;
    BoxCount : INT := 0;
END_VAR
IF RunCmd THEN
    MotorOut := TRUE;
    IF PE_Sensor THEN
        BoxCount := BoxCount + 1;
    END_IF;
ELSE
    MotorOut := FALSE;
END_IF;
END_FUNCTION_BLOCK
